// Tests for the BACKLOG.md items. tests/text.test.js is untouched on purpose — it pins the
// behaviour that must keep working.
const test = require('node:test');
const assert = require('node:assert');
const { slugify, truncate, wordCount, readingTime } = require('../src/text');

test('slugify transliterates Cyrillic', () => {
  assert.strictEqual(slugify('Привет мир'), 'privet-mir');
  assert.strictEqual(slugify('Ёлка'), 'elka');
  assert.strictEqual(slugify('Съешь ещё'), 'sesh-eshche');
  // Latin behaviour is unchanged.
  assert.strictEqual(slugify('Hello World'), 'hello-world');
});

test('truncate can cut on a word boundary', () => {
  const s = 'the quick brown fox';
  assert.strictEqual(truncate(s, 13, '…', { wordBoundary: true }), 'the quick…');
  // The cut already lands after a whole word — keep it.
  assert.strictEqual(truncate(s, 10, '…', { wordBoundary: true }), 'the quick…');
  // Fits: returned unchanged whatever the options say.
  assert.strictEqual(truncate(s, 50, '…', { wordBoundary: true }), s);
  // One word longer than the budget has no boundary to fall back to.
  assert.strictEqual(truncate('abcdefghij', 5, '…', { wordBoundary: true }), 'abcd…');
  // Default stays the old mid-word behaviour.
  assert.strictEqual(truncate(s, 13), 'the quick br…');
  assert.strictEqual(truncate(s, 13, '...'), 'the quick ...');
});

test('wordCount counts what a reader sees, not markdown syntax', () => {
  assert.strictEqual(wordCount('**bold** text'), 2);
  assert.strictEqual(wordCount('_em_ and __strong__ and `code`'), 5);
  assert.strictEqual(wordCount('[the docs](https://example.com/a/b)'), 2);
  assert.strictEqual(wordCount('see [the docs](https://example.com) now'), 4);
  assert.strictEqual(wordCount('# Heading one'), 2);
  assert.strictEqual(wordCount('- one\n- two\n1. three'), 3);
  assert.strictEqual(wordCount('> quoted words here'), 3);
  assert.strictEqual(wordCount('![alt text](img.png)'), 0);
  assert.strictEqual(wordCount('---'), 0);
  // Plain text is unaffected.
  assert.strictEqual(wordCount('one two three'), 3);
  assert.strictEqual(wordCount('   '), 0);
});

test('readingTime is whole minutes at 200 wpm', () => {
  const words = (n) => Array.from({ length: n }, () => 'word').join(' ');
  assert.strictEqual(readingTime(''), 0);
  assert.strictEqual(readingTime('   '), 0);
  assert.strictEqual(readingTime('one'), 1);
  assert.strictEqual(readingTime(words(200)), 1);
  assert.strictEqual(readingTime(words(201)), 2);
  assert.strictEqual(readingTime(words(600)), 3);
});

