'use strict';

// Text utilities. Small on purpose: the interesting part is the backlog, not the code.

const ACRONYMS = new Set(['API', 'HTTP', 'SQL', 'URL', 'CSS']);

// Cyrillic → Latin, keyed on lowercase because slugify lowercases before it transliterates.
// Covers Russian plus the letters Ukrainian/Belarusian add; soft and hard signs drop out.
const CYRILLIC_TO_LATIN = {
  а: 'a', б: 'b', в: 'v', г: 'g', ґ: 'g', д: 'd', е: 'e', ё: 'e', є: 'ye', ж: 'zh',
  з: 'z', и: 'i', і: 'i', ї: 'yi', й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o',
  п: 'p', р: 'r', с: 's', т: 't', у: 'u', ў: 'u', ф: 'f', х: 'h', ц: 'ts', ч: 'ch',
  ш: 'sh', щ: 'shch', ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya',
};

function transliterate(s) {
  return s.replace(/[Ѐ-ӿ]/g, (ch) => CYRILLIC_TO_LATIN[ch] ?? '');
}

function slugify(input) {
  return transliterate(String(input).trim().toLowerCase())
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

const ELLIPSIS = '…';

function truncate(input, maxLength, suffix = ELLIPSIS, options = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;
  const room = Math.max(0, maxLength - suffix.length);
  let head = s.slice(0, room);
  if (options.wordBoundary) {
    // Only chop back when the cut landed inside a word: if the next character is whitespace,
    // the last word in `head` is complete. A single word longer than the budget has no boundary
    // to fall back to, so it stays hard-cut.
    if (!/\s/.test(s[room] ?? ' ')) head = head.replace(/\s+\S*$/, '');
    head = head.replace(/\s+$/, '');
  }
  return head + suffix;
}

function capitalize(input) {
  const s = String(input);
  if (!s) return s;
  return s[0].toUpperCase() + s.slice(1);
}

// Reduce markdown to the words a reader actually sees: link text stays, the URL goes, and syntax
// (heading hashes, list bullets, emphasis markers, fences) leaves nothing behind to be counted.
function stripMarkdown(input) {
  return String(input)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ') // images: a reader sees a picture, not words
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // inline links: keep the text, drop the URL
    .replace(/\[([^\]]*)\]\[[^\]]*\]/g, '$1') // reference links
    .replace(/^ {0,3}\[[^\]]*\]:.*$/gm, ' ') // link definitions
    .replace(/<[^>\s]*>/g, ' ') // autolinks and raw html tags
    .replace(/^ {0,3}```.*$/gm, ' ') // code fences (the code inside is still read)
    .replace(/^ {0,3}#{1,6}\s+/gm, '') // heading hashes
    .replace(/^ {0,3}>\s?/gm, '') // blockquote markers
    .replace(/^ {0,3}([-*_])(\s*\1){2,}\s*$/gm, ' ') // horizontal rules
    .replace(/^ {0,3}([-*+]|\d+[.)])\s+/gm, '') // list bullets
    .replace(/[*_~`]/g, ''); // emphasis and inline-code markers
}

function splitWords(input) {
  const s = String(input).trim();
  return s ? s.split(/\s+/) : [];
}

function wordCount(input) {
  return splitWords(stripMarkdown(input)).length;
}

function excerpt(input, maxWords) {
  const s = String(input);
  const words = splitWords(s);
  if (words.length <= maxWords) return s;
  return words.slice(0, maxWords).join(' ') + ELLIPSIS;
}

// Ampersand first, so the ampersands introduced by the later entities are not escaped again.
const HTML_ESCAPES = [
  ['&', '&amp;'],
  ['<', '&lt;'],
  ['>', '&gt;'],
  ['"', '&quot;'],
  ["'", '&#39;'],
];

function escapeHtml(input) {
  let s = String(input);
  for (const [char, entity] of HTML_ESCAPES) s = s.split(char).join(entity);
  return s;
}

const WORDS_PER_MINUTE = 200;

function readingTime(input) {
  const words = wordCount(input);
  if (!words) return 0;
  return Math.max(1, Math.ceil(words / WORDS_PER_MINUTE));
}

// `acronyms` is any iterable of words to leave uppercase; it replaces the built-in list rather than
// extending it. Entries are matched case-insensitively.
function titleCase(input, acronyms = ACRONYMS) {
  const known = new Set(Array.from(acronyms, (a) => String(a).toUpperCase()));
  return String(input)
    .split(/\s+/)
    .map((w) => (known.has(w.toUpperCase()) ? w.toUpperCase() : capitalize(w.toLowerCase())))
    .join(' ');
}

module.exports = {
  slugify,
  truncate,
  capitalize,
  wordCount,
  excerpt,
  readingTime,
  escapeHtml,
  titleCase,
  ACRONYMS,
};

